#!/bin/bash
# install-lab-docs.sh — recreate the lab documentation set on the mgmt node.
# Run from the project root:  bash install-lab-docs.sh
# Places 7 guides + 3 SVGs into docs/ and run-facts-export-prod.sh into scripts/.
set -euo pipefail
cd "$(dirname "$0")"

if [ ! -f ansible.cfg ] && [ ! -d playbooks ]; then
  echo "WARNING: this does not look like the project root (no ansible.cfg/playbooks)."
  echo "cd to /etc/ansible/Ansible_Simulator_Lab first, then re-run."
  read -rp "Continue anyway? [y/N] " a; [ "$a" = "y" ] || exit 1
fi

mkdir -p docs scripts

echo "  writing docs/Lab-Guide-Rocky9-AccessControl.html"
base64 -d > 'docs/Lab-Guide-Rocky9-AccessControl.html' <<'B64EOF'
